PRAGMA foreign_keys=ON;
CREATE TABLE IF NOT EXISTS users(id INTEGER PRIMARY KEY, username TEXT UNIQUE NOT NULL, name TEXT NOT NULL, password_hash TEXT NOT NULL, role TEXT NOT NULL CHECK(role IN ('owner','admin','reviewer','member','reader')), must_change INTEGER NOT NULL DEFAULT 1, active INTEGER NOT NULL DEFAULT 1, membership TEXT NOT NULL DEFAULT 'pending' CHECK(membership IN ('pending','official')), membership_reference TEXT NOT NULL DEFAULT '', created TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS sessions(token_hash TEXT PRIMARY KEY, user_id INTEGER REFERENCES users(id), csrf TEXT NOT NULL, expires INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS limits(key TEXT PRIMARY KEY, count INTEGER NOT NULL, until INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS documents(slug TEXT PRIMARY KEY, title TEXT NOT NULL, intro TEXT NOT NULL DEFAULT '', version INTEGER NOT NULL, status TEXT NOT NULL DEFAULT 'proposal', html TEXT NOT NULL, updated TEXT NOT NULL, reference TEXT NOT NULL DEFAULT '');
CREATE TABLE IF NOT EXISTS revisions(id INTEGER PRIMARY KEY, document TEXT NOT NULL REFERENCES documents(slug), version INTEGER NOT NULL, html TEXT NOT NULL, status TEXT NOT NULL, reason TEXT NOT NULL, reference TEXT NOT NULL DEFAULT '', author INTEGER REFERENCES users(id), source_thread INTEGER, created TEXT NOT NULL, UNIQUE(document,version));
CREATE TABLE IF NOT EXISTS threads(id INTEGER PRIMARY KEY, document TEXT NOT NULL REFERENCES documents(slug), version INTEGER NOT NULL, section TEXT NOT NULL, section_title TEXT NOT NULL, section_snapshot TEXT NOT NULL, quote TEXT NOT NULL DEFAULT '', prefix TEXT NOT NULL DEFAULT '', suffix TEXT NOT NULL DEFAULT '', title TEXT NOT NULL, topic TEXT NOT NULL, author INTEGER NOT NULL REFERENCES users(id), state TEXT NOT NULL DEFAULT 'open' CHECK(state IN ('open','closing','archived')), summary TEXT NOT NULL DEFAULT '', outcome TEXT NOT NULL DEFAULT '', revision_id INTEGER REFERENCES revisions(id), created TEXT NOT NULL, updated TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS comments(id INTEGER PRIMARY KEY, thread_id INTEGER NOT NULL REFERENCES threads(id), author INTEGER NOT NULL REFERENCES users(id), body TEXT NOT NULL, created TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS reviews(id INTEGER PRIMARY KEY, thread_id INTEGER NOT NULL REFERENCES threads(id), payload TEXT NOT NULL, source TEXT NOT NULL, comment_count INTEGER NOT NULL, document_version INTEGER NOT NULL, approved INTEGER NOT NULL DEFAULT 0, author INTEGER NOT NULL REFERENCES users(id), created TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS events(id INTEGER PRIMARY KEY, thread_id INTEGER REFERENCES threads(id), actor INTEGER REFERENCES users(id), kind TEXT NOT NULL, detail TEXT NOT NULL, created TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS ai_jobs(id INTEGER PRIMARY KEY, thread_id INTEGER NOT NULL REFERENCES threads(id), actor INTEGER NOT NULL REFERENCES users(id), state TEXT NOT NULL DEFAULT 'queued', error TEXT NOT NULL DEFAULT '', created TEXT NOT NULL, started TEXT, finished TEXT);
CREATE INDEX IF NOT EXISTS idx_comments_thread ON comments(thread_id,id);
CREATE INDEX IF NOT EXISTS idx_events_thread ON events(thread_id,id);
CREATE INDEX IF NOT EXISTS idx_reviews_thread ON reviews(thread_id,id);
CREATE INDEX IF NOT EXISTS idx_jobs_state ON ai_jobs(state,id);
